@-moz-document domain("search.brave.com") {
/* 🖥️ More Results + Main Layout */


/* Removes sidebar if sidebar has no contents or isn't relevant (Improves loading + layout?) */
.column-layout.noscrollbar.has-sidebar aside {display: none !important;}
.column-layout.noscrollbar.has-sidebar aside:has(#infobox-snippet) {
	display: flex !important;
	flex-direction: column;
	gap: 8px;
    padding: var(--spacing-2xl) 0;
}
aside #infobox-snippet #codebox:has(#codebox-answer) {padding: var(--spacing-2xl);}
#codebox-header {padding-bottom: 0px !important;}


/* Search: https://search.brave.com/search?q=New+York+restaurant */
.column-layout.noscrollbar:has(#info-banners) {align-items: center;}
.column-layout.noscrollbar:has(#info-banners) #altered-query {margin: 0;}


/* ====> More Results <=== */
#search-page main.main-column #results {
  display: grid !important;
  grid-template-columns: repeat(auto-fill,minmax(760px,1fr));   /* Higher than 800 = half-screen sidebar offset */
  gap: 8px;
  overflow: hidden;
  min-height: auto !important;
}
#search-page .column-layout { /* Whole page? */
    max-width: var(--main-column-width);
    padding: 0;
	}
#results.section:first-child {margin-right: 0vw;}
/* Top Stories */
#rh.snippet.standalone:has(#news-content) :is(#news-content, #news-content-extra) {padding: 0 6px;}
/* => Next & Previous Page container <= */
#pagination-snippet {
  grid-column-start: auto;
  grid-column-end: -1;
  height: fit-content;
  background: transparent;
}
/* ==> Tweaks / Fixes <== */
.snippet:not(.standalone) + .snippet:not(.standalone) { /* Stupid attached snippet */
  margin-top: calc(0 * var(--spacing-2xl)) !important;
	outline: 1px solid var(--color-divider-subtle);
  border-width: 0px;
}
#calculator,
#rh.snippet.standalone,
#timer.snippet.standalone,
.snippet:not(.standalone), #featured-snippet {padding: calc(var(--spacing-2xl) - 5px) var(--spacing-2xl) var(--spacing-2xl) var(--spacing-2xl) !important;}
.snippet.standalone {margin: 0 !important;}
/* Sidebar */
#infobox > section {padding: 0 0 !important;}
/* Discussion header + Other header */
#codellm {padding-top: var(--spacing-2xl);}
.rich-snippet-content {padding: 0 var(--spacing-2xl) var(--spacing-l) !important;}
.header-container {padding: 0 !important;}
/* Removals */
#search-elsewhere, #related-queries {display: none;}



/* ===========> Videos, News & Other standalone snippet fixes | Update with autofill <=========== */
/* In the news */
#results .snippet.standalone:has([data-type="news"]) {grid-row: 10 / span 2; grid-column: 1 / span 1;}
/* Videos */
#results .snippet.standalone:has([data-type="video"]) {grid-row: 10 / span 3; grid-column: 2 / span 1;}
/* Top Stories */
#rh.snippet.standalone:has(#news-content) {grid-row: 1 / span 5; grid-column: 1 / span 1;}


/* Films/Series Snippets | https://search.brave.com/search?q=Resident+Evil+movies+in+order */
#pe {grid-row: 5 / span 2; grid-column: 2 / span 1;}
/* Maps on All page */
.snippet.standalone:has(#map-view) {grid-row: 1 / span 3; grid-column: 2 / span 1;}
/* Code snippet */
#llm-snippet {grid-row: 1 / span 9; grid-column: 1 / span 1;}
#codellm {grid-row: 1 / span 8; grid-column: 1 / span 1;}


#results > #rh.snippet.standalone {grid-row: 1 / span 3; grid-column: 1 / span 1;}


/* ======> Videos, In news, standalone snippets <====== */
.carousel-container .carousel {
  display: grid !important;
  grid-template-columns: repeat(auto-fill,minmax(190px,1fr));
  --card-gutter: 0px !important;
  max-height: 239px;
  overflow-x: hidden !important;
  border-right: 1px solid var(--color-divider-subtle);
  border-left: 1px solid var(--color-divider-subtle);
}
.carousel-container .carousel:has([data-type="video"]) {max-height: 235px;}
.carousel-container .carousel .card {
  width: auto !important;
  max-width: 230px;
  border-right-width: 0px;
  background: var(--color-serp-snippet-background);
}
.carousel-container .carousel .card:nth-of-type(1) {border-left-width: 0px;}
.carousel-container .slide-button {display: none !important;}
#results .snippet.standalone:has([data-type="news"]) .carousel-container .carousel {max-height: 228px;}
.snippet[data-type="web"]:not(.standalone) .carousel-container {display: none;} /* Shopping section + */
/* Map View */

button#map-view {grid-column-start: 1; grid-column-end: -1;}
/* Padding fix */
.snippet.standalone .carousel .framed {padding: 0 !important;}
.snippet.standalone .carousel .framed :is(.card-body, .card-footer) {padding-inline: var(--spacing-m) !important;}

/* ======> Discussions snippet <====== */
#discussions {
  order: 2 !important;
  grid-column-start: 1;
  grid-column-end: -1;
  padding: 0px !important;
}
/* More results */
#discussions {
  display: grid !important;
  grid-template-columns: repeat(auto-fill,minmax(795px,1fr));
  gap: 8px;
  padding: 0 var(--spacing-2xl) !important;
  background: #ff910014 !important;
}
#discussions .snippet-fullwidth {grid-column-start: 1; grid-column-end: -1; display: none;}
/* Fixes / OCD stuff */
#discussions details {
  border-color: transparent;
  padding: calc(var(--spacing-xl) - 4px) 0;
}
.fq-item.transitioning {background: transparent;}
.discussions-item > .accordion-item,
#discussions summary .question {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(360px,1fr));
  gap: 6px;
  overflow: hidden;
  max-width: 100% !important;
}
#discussions summary > button,
.button.size--tiny.type--outlined.theme--default.icon-only.icon-end.type {border-color: transparent;}
#discussions :is(header.desktop-heading-h4, hr.snippet-divider, button.icon-only.icon-end.tooltip--bottom) {display: none;}

/* Removals */
#discussions .question .desktop-small-regular.meta :is(div.item:nth-of-type(n+2), span.dot:nth-of-type(n+2)) {display: none;}
#search-page .snippet > .video-snippet, .snippet.standalone:has(.video-item.flex) {display: none;}
#search-page #results > .snippet:has(.image-cluster),
#results .snippet[data-type="videos"] {display: none;}
}

@-moz-document domain("search.brave.com") {
/* 🥂 Main Content | Everything */

#search-page {margin: auto var(--main-gap);}

    div[class="sidebar-header svelte-1k81x2q"]{
