.inline-qa-question,
.snippet-description {-webkit-line-clamp: 1 !important;}
.inline-qa-question ol,
.inline-qa-question > table,
.inline-qa-question > p {display: none;}
/* Definition */
section.svelte-oe6hwk.svelte-oe6hwk:not(:last-of-type) {margin-bottom: 0;}
#definition .attribution {display: none;}



/* ==========> Removals <========== */
