.snippet:not(.standalone) .product-cluster,
.snippet :is(.snippet-fullwidth.noscrollbar:has([data-type="product"]), .item-attributes, .attributes, .result-cluster, .video-thumb, .product, .deep-links, .snippet-content .thumb),
.snippet:not(.standalone) .zoom.general.thumbnail {display: none;}
